"""Isolated multi-session agent benchmark for ARGOS-VIBE (one physical server).

Research task, stage 5. Runs N agent sessions as SEPARATE PROCESSES on this
sandbox, each fully isolated:

  * own SQLite files under data/isolation/session_<i>/ (brain.db, cognitive.db)
  * own original ArgosMasterCore + CognitiveMemory instances
  * only synthetic messages generated by this script; no external traffic,
    no other environments touched, nothing outside /workspace/argos-runtime

Measured per session (wall-clock, perf_counter):
  memory_write_ms   remember: k | v via original ArgosMemory
  memory_read_ms    recall: k
  shell_ms          shell echo (allowlisted executor)
  llm_ms            think: via NeuralNexus -> llama.cpp Qwen2.5-0.5B
  total_ms          whole session

The LLM server is shared, so llm_ms under N parallel sessions measures real
contention on the single inference backend — reported honestly.
"""
from __future__ import annotations

import json
import os
import statistics
import sys
import time
from datetime import datetime, timezone
from multiprocessing import Process, Queue

REPO = os.getenv("ARGOS_REPO", "/workspace/github__winargos42-dotcom__argos")
RUNTIME = os.getenv("ARGOS_RUNTIME", "/workspace/argos-runtime")
SESSIONS = int(os.getenv("ARGOS_ISO_SESSIONS", "3"))
ROUNDS = int(os.getenv("ARGOS_ISO_ROUNDS", "2"))
REPORT = os.getenv("ARGOS_ISO_REPORT", f"{RUNTIME}/session_isolation_report.json")


def now() -> str:
    return datetime.now(timezone.utc).isoformat()


def session_worker(idx: int, rounds: int, q: Queue) -> None:
    sys.path.insert(0, REPO)
    data_dir = f"{RUNTIME}/data/isolation/session_{idx}"
    os.makedirs(data_dir, exist_ok=True)
    os.chdir(RUNTIME)
    os.environ["ARGOS_LOG_DIR"] = f"{RUNTIME}/logs"
    os.environ["ARGOS_COGNITIVE_SQLITE"] = f"{data_dir}/cognitive.db"
    os.environ["ARGOS_PG_ENABLED"] = "0"

    from src.swarm.argos_master_core import ArgosMasterCore
    from src.cognitive_memory import CognitiveMemory

    master = ArgosMasterCore(db_path=f"{data_dir}/brain.db")
    cm = CognitiveMemory(prefer_pg=False)
    master.ac.approve("admin")

    samples = {"memory_write_ms": [], "memory_read_ms": [], "shell_ms": [],
               "llm_ms": [], "total_ms": []}
    for r in range(rounds):
        t_all = time.perf_counter()
        t0 = time.perf_counter()
        master.execute(f"remember: iso_{idx}_{r} | synthetic value {idx}/{r}",
                       user_id="admin")
        samples["memory_write_ms"].append((time.perf_counter() - t0) * 1000)

        t0 = time.perf_counter()
        master.execute(f"recall: iso_{idx}_{r}", user_id="admin")
        samples["memory_read_ms"].append((time.perf_counter() - t0) * 1000)

        t0 = time.perf_counter()
        master.execute(f"shell echo SESSION_{idx}_ROUND_{r}", user_id="admin")
        samples["shell_ms"].append((time.perf_counter() - t0) * 1000)

        t0 = time.perf_counter()
        llm = master.execute(f"think: Ответь одним словом: 2+2=?", user_id="admin")
        samples["llm_ms"].append((time.perf_counter() - t0) * 1000)

        cm.log_event("isolation", "round_done", {"session": idx, "round": r,
                                                 "llm_ms": samples["llm_ms"][-1]})
        samples["total_ms"].append((time.perf_counter() - t_all) * 1000)

    cm.reflect(f"Сессия {idx}: {rounds} раундов изолированной работы",
               {"rounds": rounds, "llm_ms_last": samples["llm_ms"][-1]})
    cm.close()
    q.put({"session": idx, "node_id": master.node_id,
           "db_dir": data_dir, "llm_answer_sample": llm[:120], "samples": samples})


def pct(values: list[float], p: float) -> float:
    s = sorted(values)
    return round(s[min(len(s) - 1, int(len(s) * p))], 2)


def main() -> int:
    q: Queue = Queue()
    t0 = time.perf_counter()
    procs = [Process(target=session_worker, args=(i, ROUNDS, q)) for i in range(SESSIONS)]
    for p in procs:
        p.start()
    results = [q.get() for _ in procs]
    for p in procs:
        p.join(30)
    wall_s = time.perf_counter() - t0

    agg = {}
    for key in ("memory_write_ms", "memory_read_ms", "shell_ms", "llm_ms", "total_ms"):
        flat = [v for r in results for v in r["samples"][key]]
        agg[key] = {"n": len(flat), "min": round(min(flat), 2),
                    "median": statistics.median(flat), "p95": pct(flat, 0.95),
                    "max": round(max(flat), 2)}
        if key == "llm_ms":
            agg[key] = {**agg[key], "median": round(statistics.median(flat), 2)}

    report = {
        "generated_at": now(),
        "host_note": "single physical sandbox, 4.0 CPU cgroup cores, 3.95 GiB RAM, "
                     "shared llama.cpp Qwen2.5-0.5B on loopback :11434",
        "sessions": SESSIONS, "rounds": ROUNDS,
        "wall_s": round(wall_s, 2),
        "aggregate_ms": agg,
        "per_session": results,
    }
    with open(REPORT, "w") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
    print(json.dumps({"sessions": SESSIONS, "rounds": ROUNDS, "wall_s": round(wall_s, 2),
                      "aggregate_ms": agg}, indent=2, ensure_ascii=False))
    print(f"report: {REPORT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
